          if (value < 1) {
            callback(new Error('时长不能小于1分钟'));
          } else if (value > 1440) {
            callback(new Error('时长不能超过24小时'));
          } else {
            callback();
          }
        },
        trigger: 'blur'
      }]
    };

    // 计算属性
    const availableContainers = computed(() => {
      return (containersRef.value?.containers || []).filter(c => c.state === 'running');
    });
    const calculatedRestoreTime = computed(() => {
      if (!formData.value.duration) return '';
      const minutes = formData.value.unit === 'hours' ? formData.value.duration * 60 : formData.value.duration;
      const date = new Date(Date.now() + minutes * 60000);
      return date.toLocaleString();
    });
    const statusIcon = computed(() => {
      return currentTask.value?.type === 'stop' ? 'CircleClose' : 'SuccessFilled';
